/* Read a list by canonical path. `fallback` is returned when this file did not
   load or the path was never captured, so a consumer degrades to its old literal
   instead of rendering an empty dropdown. Always returns a fresh array — callers
   spread and sort these, and a shared array would let one picker corrupt another. */
window.arenaChoice = function (path, fallback) {
  var list = window.ARENA_CHOICES && window.ARENA_CHOICES[path];
  return Array.isArray(list) && list.length ? list.slice() : (fallback || []).slice();
};

/* The phase sources a parameter can be driven by, labelled for the entity that
   owns it: entity_fft is ONE source that Arena shows as Clip/Layer/Group/
   Composition FFT depending on the owner. On the composition it would collide
   with composition_fft, so it is dropped there rather than listed twice. */
window.arenaPhaseSources = function (entity) {
  var A = window.ARENA_ANIMATION;
  if (!A) return [];
  var own = A.entity_fft_labels[entity] || A.entity_fft_labels.Clip;
  return A.phase_sources
    .filter(function (id) { return !(id === 'entity_fft' && entity === 'Composition'); })
    .map(function (id) { return id === 'entity_fft' ? own : A.phase_labels[id]; });
};
